# Try more hypotheses - let's test a few more patterns

import numpy as np

grid = np.array([[int(x) for x in line.strip().split()] for line in grid_str.strip().split('\n')])

# Hypothesis 3: Each cell takes the most common color among its immediate non-zero neighbors (not including self)
def get_neighbor_dominant(grid):
    h, w = grid.shape
    output = np.zeros((h, w), dtype=int)

    for r in range(h):
        for c in range(w):
            if grid[r, c] != 0:
                # Count orthogonal neighbors of different colors
                neighbor_colors = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w:
                        neighbor_colors.append(grid[nr, nc])

                counts = {}
                for val in neighbor_colors:
                    if val != 0:
                        counts[val] = counts.get(val, 0) + 1

                if counts:
                    output[r, c] = max(counts.keys(), key=lambda k: counts[k])
                else:
                    output[r, c] = grid[r, c]
            else:
                output[r, c] = 0

    return output

output_grid3 = get_neighbor_dominant(grid)
print("Hypothesis 3 (neighbor dominant, excluding zero):")
print(output_grid3)

# Hypothesis 4: Maybe count distinct colors in each 5x5 region?
def count_distinct_per_region(grid):
    h, w = grid.shape
    output = np.zeros((h, w), dtype=int)
    regions_per_side = 5

    for ri in range(regions_per_side):
        for ci in range(regions_per_side):
            rmin, rmax = ri * h // regions_per_side, (ri + 1) * h // regions_per_side
            cmin, cmax = ci * w // regions_per_side, (ci + 1) * w // regions_per_side

            region = grid[rmin:rmax, cmin:cmax]
            distinct_nonzero = set(region.flatten()) - {0}
            # Map count of distinct colors (1-5) to that value
            num_distinct = len(distinct_nonzero)

            for r in range(rmin, rmax):
                for c in range(cmin, cmax):
                    output[r, c] = num_distinct

    return output

output_grid4 = count_distinct_per_region(grid)
print("\n\nHypothesis 4 (count distinct non-zero colors per 5x5 region):")
print(output_grid4)

