# Try hypothesis: Each cell becomes its most common neighbor color (excluding background)
def get_neighbor_dominant(grid):
    n = grid.shape[0]
    result = np.zeros((n, n), dtype=int)

    for i in range(n):
        for j in range(n):
            # Get all 8 neighbors
            neighbors = []
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0:
                        continue
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < n:
                        neighbors.append(grid[ni, nj])

            # Count non-background colors
            color_counts = {}
            for c in neighbors:
                if c != 0:
                    color_counts[c] = color_counts.get(c, 0) + 1

            if color_counts:
                max_count = max(color_counts.values())
                candidates = [c for c, cnt in color_counts.items() if cnt == max_count]
                result[i, j] = min(candidates)  # Pick smallest as tiebreaker
            else:
                result[i, j] = 0

